def main():
    verbs = []
    seen = set()
    for row in RAW_VERBS:
        v1, v2, v3, ipa1, ipa2, ipa3, vi, morph, cefr, rank, ex, ex_vi = row
        slug = v1.replace(" ", "-").replace("/", "-").lower()
        if slug in seen:
            slug = f"{slug}-{rank}"
        seen.add(slug)
        verbs.append({
            "id": slug,
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "ipa_v1": ipa1,
            "ipa_v2": ipa2,
            "ipa_v3": ipa3,
            "meaning_vi": vi,
            "morph_group": morph,
            "cefr_level": cefr,
            "common_rank": rank,
            "example_sentence": ex,
            "example_sentence_vi": ex_vi
        })

    out_path = os.path.join(os.path.dirname(__file__), "verbs_360.json")
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(verbs, f, ensure_ascii=False, indent=2)

    print(f"Successfully generated {len(verbs)} irregular verbs to {out_path}")

if __name__ == "__main__":
    main()
